draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw dog
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 30);
  ctx.lineTo(W/2 + Math.sin(t) * 50, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 70);
  ctx.lineTo(W/2 + Math.sin(t) * 50 - 30, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 70);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + 30, H/2 + 100);
  ctx.stroke();

  // draw tail
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 100);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + Math.sin(t * 2) * 20, H/2 + 130);
  ctx.stroke();

  // draw ear
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50 - 15, H/2 - 30);
  ctx.lineTo(W/2 + Math.sin(t) * 50 - 30, H/2 - 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50 + 15, H/2 - 30);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + 30, H/2 - 50);
  ctx.stroke();

  ctx.restore();
}
